import { test, expect } from '@playwright/test';

test.describe('Secure Area Login - Returning User', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
  });

  test('should successfully log in a returning user and access secure area', async ({ page }) => {
    // Verify login form fields are visible
    const usernameField = page.getByLabel('Username');
    const passwordField = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(usernameField).toBeVisible();
    await expect(passwordField).toBeVisible();
    await expect(loginButton).toBeVisible();

    // Fill in credentials
    await usernameField.fill('tomsmith');
    await passwordField.fill('SuperSecretPassword!');

    // Click login button
    await loginButton.click();

    // Verify navigation to secure area
    await expect(page).toHaveURL(/.*secure/);

    // Verify success flash banner is displayed
    const successBanner = page.locator('.flash.success');
    await expect(successBanner).toBeVisible();
    await expect(successBanner).toContainText('You logged into a secure area!');

    // Verify secure content is visible
    const secureContent = page.getByText('Secure Area');
    await expect(secureContent).toBeVisible();
  });

  test('should display error message when login fails with invalid credentials', async ({ page }) => {
    // Fill in invalid credentials
    const usernameField = page.getByLabel('Username');
    const passwordField = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameField.fill('wronguser');
    await passwordField.fill('wrongpassword');

    // Click login button
    await loginButton.click();

    // Verify user remains on login page
    await expect(page).toHaveURL(/.*login/);

    // Verify error message is displayed
    const errorBanner = page.locator('.flash.error');
    await expect(errorBanner).toBeVisible();
    await expect(errorBanner).toContainText('Invalid username or password');

    // Verify secure content is not visible
    const secureContent = page.getByText('Secure Area');
    await expect(secureContent).not.toBeVisible();
  });
});
